async function token(){if(antiforgeryToken)return antiforgeryToken;const response=await fetch('/api/account/antiforgery',{credentials:'include'});if(!response.ok)throw new Error('Could not establish request protection.');return antiforgeryToken=(await response.json()).token;}
async function api(path,init={}){const method=(init.method||'GET').toUpperCase(),headers=new Headers(init.headers);if(!['GET','HEAD','OPTIONS'].includes(method)){headers.set('Content-Type','application/json');headers.set('X-XSRF-TOKEN',await token());}const response=await fetch(path,{...init,headers,credentials:'include'});if(!response.ok)throw new Error((await response.json().catch(()=>null))?.title||`Server request failed (${response.status}).`);if(response.status===204)return null;return response.json();}
async function loadState(){try{const saved=await api('/api/fantasy/workspace');if(saved?.state)return validateBackup(saved.state);}catch(e){storageError='The server workspace could not be loaded. Using this browser’s last copy.';}const raw=localStorage.getItem(STORAGE);return raw?validateBackup(JSON.parse(raw)):initialState();}
