let analysisCache=null;
function analysis(s,r){if(analysisCache?.state===s&&analysisCache.room===r)return analysisCache.result;const result=computeAnalysis(s,r);analysisCache={state:s,room:r,result};return result;}
function save(){analysisCache=null;try{rememberDraftDefaults(state,room());localStorage.setItem(STORAGE,JSON.stringify(state));storageError='';clearTimeout(syncTimer);syncTimer=setTimeout(()=>{syncTimer=null;api('/api/fantasy/workspace',{method:'PUT',body:JSON.stringify({state})}).catch(e=>{storageError=`Server sync paused: ${e.message}`;render();});},350);}catch(e){storageError='Browser storage is full or unavailable. Export a backup now; this session is only in memory.';}render();}
async function flushWorkspace(){if(conflict)return false;try{clearTimeout(syncTimer);syncTimer=null;await api('/api/fantasy/workspace',{method:'PUT',body:JSON.stringify({state})});storageError='';return true;}catch(e){storageError=`Server sync paused: ${e.message}`;render();return false;}}
async function refreshWorkspace(){try{if(syncTimer){clearTimeout(syncTimer);syncTimer=null;await api('/api/fantasy/workspace',{method:'PUT',body:JSON.stringify({state})});}const saved=await api('/api/fantasy/workspace');if(saved?.state){const loaded=validateBackup(saved.state),previousActive=loaded.active,previousCount=loaded.rooms.length;state=ensureActiveRoom(loaded);if(state.active!==previousActive||state.rooms.length!==previousCount)await api('/api/fantasy/workspace',{method:'PUT',body:JSON.stringify({state})});localStorage.setItem(STORAGE,JSON.stringify(state));}storageError='';conflict=false;selected.clear();analysisCache=null;render();return true;}catch(e){storageError=`The server workspace could not be refreshed: ${e.message}`;render();return false;}}
function mergeCanonicalPlayers(duplicateId,targetId,targetName){return mutate(()=>{for(const source of state.sources)for(const player of source.players)if(player.canonicalPlayerId===duplicateId){player.canonicalPlayerId=targetId;player.canonicalName=targetName;player.canonicalMatchType='merged alias';}for(const draftRoom of state.rooms)for(const pick of draftRoom.picks)if(pick.player?.id===duplicateId){pick.player.id=targetId;pick.player.canonicalPlayerId=targetId;pick.player.canonicalName=targetName;}});}
function mutate(fn){if(conflict){toast('Reload this tab to use the latest saved state.');return false;}try{fn();save();return true;}catch(e){toast(e.message);return false;}}
